#include "TacticalFPSFoundation.h"
#include "Engine/World.h"
#include "GameFramework/Pawn.h"

UTacticalInteractComponent::UTacticalInteractComponent()
{
  SetIsReplicatedByDefault(true);
  PrimaryComponentTick.bCanEverTick = false;
}

void UTacticalInteractComponent::BeginPlay()
{
  Super::BeginPlay();
  const float Period = TraceInterval > 0.f ? TraceInterval : 0.1f;
  GetWorld()->GetTimerManager().SetTimer(TraceTimer, this, &UTacticalInteractComponent::TraceForFocus, Period, true);
}

void UTacticalInteractComponent::TraceForFocus()
{
  APawn* OwnerPawn = Cast<APawn>(GetOwner());
  if (!OwnerPawn) return;
  const FVector Start = OwnerPawn->GetPawnViewLocation();
  const FVector End = Start + OwnerPawn->GetControlRotation().Vector() * TraceDistance;
  FCollisionQueryParams Params(SCENE_QUERY_STAT(TacticalInteract), false);
  if (bIgnorePlayer) Params.AddIgnoredActor(OwnerPawn);
  FHitResult Hit;
  const bool bHit = GetWorld()->LineTraceSingleByChannel(Hit, Start, End, ECC_Visibility, Params);
  AActor* Next = nullptr;
  if (bHit && Hit.GetActor() && Hit.GetActor()->GetClass()->ImplementsInterface(UTacticalInteractable::StaticClass()))
  {
    Next = Hit.GetActor();
  }
  if (Next == FocusedActor.Get()) return;
  FocusedActor = Next;
  OnFocusChanged.Broadcast(Next);
}

void UTacticalInteractComponent::TryInteract()
{
  if (!FocusedActor.IsValid() || !GetOwner()) return;
  if (GetOwner()->HasAuthority()) ServerTryInteract_Implementation();
  else ServerTryInteract();
}

void UTacticalInteractComponent::ServerTryInteract_Implementation()
{
  AActor* Target = FocusedActor.Get();
  if (!Target || !GetOwner() || !GetOwner()->HasAuthority()) return;
  if (ITacticalInteractable* Interactable = Cast<ITacticalInteractable>(Target))
  {
    Interactable->Interact(GetOwner());
    LastInteractId++;
  }
}

void UTacticalInteractComponent::OnRep_LastInteractId()
{
  if (LastInteractId > 0) OnFocusChanged.Broadcast(FocusedActor.Get());
}

void UTacticalInteractComponent::GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const
{
  Super::GetLifetimeReplicatedProps(OutLifetimeProps);
  DOREPLIFETIME(UTacticalInteractComponent, LastInteractId);
}

bool UTacticalInventoryComponent::AddItem(UTacticalItemData* Item)
{
  if (!Item || !GetOwner() || !GetOwner()->HasAuthority()) return false;
  int32 Count = 0;
  for (UTacticalItemData* Existing : Items)
  {
    if (Existing && Existing->ItemId == Item->ItemId) Count++;
  }
  if (Count >= Item->MaxStack) return false;
  Items.Add(Item);
  return true;
}

UTacticalWeaponWearComponent::UTacticalWeaponWearComponent()
{
  SetIsReplicatedByDefault(true);
  PrimaryComponentTick.bCanEverTick = false;
}

void UTacticalWeaponWearComponent::AddWear(float Amount)
{
  if (!GetOwner() || !GetOwner()->HasAuthority()) return;
  Wear = FMath::Clamp(Wear + (Amount > 0.f ? Amount : WearPerShot), 0.f, 1.f);
}

void UTacticalWeaponWearComponent::OnRep_Wear()
{
  Wear = FMath::Clamp(Wear, 0.f, 1.f);
}

void UTacticalWeaponWearComponent::GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const
{
  Super::GetLifetimeReplicatedProps(OutLifetimeProps);
  DOREPLIFETIME(UTacticalWeaponWearComponent, Wear);
}

UTacticalHealthComponent::UTacticalHealthComponent()
{
  SetIsReplicatedByDefault(true);
  PrimaryComponentTick.bCanEverTick = false;
}

void UTacticalHealthComponent::ApplyDamage(float Amount)
{
  if (!GetOwner() || !GetOwner()->HasAuthority()) return;
  Health = FMath::Clamp(Health - Amount, 0.f, 100.f);
}

void UTacticalHealthComponent::OnRep_Health()
{
  Health = FMath::Clamp(Health, 0.f, 100.f);
}

void UTacticalHealthComponent::GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const
{
  Super::GetLifetimeReplicatedProps(OutLifetimeProps);
  DOREPLIFETIME(UTacticalHealthComponent, Health);
}
